struct RenderVertex { float p[3],n[3],color[4],material[2],uv[2],tangent[4]={1,0,0,1}; };
struct alignas(16) GpuLight { float position_type[4],direction_range[4],color_intensity[4],cone_shadow[4]; };
struct alignas(16) GpuScene { float camera[4],ambient_exposure[4],shadow_vp[16]; int32_t counts[4]; float render_settings[4],shadow_settings[4]; GpuLight lights[8]; };
struct ShadowPush { float vp[16],model[16]; };
Mat4 shadow_ortho(float radius,float n,float f){Mat4 m{};m.v[0]=1.0f/radius;m.v[5]=-1.0f/radius;m.v[10]=1.0f/(n-f);m.v[14]=n/(n-f);m.v[15]=1.0f;return m;}
Vec3 world_pos(const Mat4&m){return {m.v[12],m.v[13],m.v[14]};}
Vec3 world_forward(const Mat4&m){return normalize({-m.v[8],-m.v[9],-m.v[10]});}
