struct DrawPush { float vp[16]; float model[16]; };
static_assert(sizeof(DrawPush)==128, "Vulkan minimum push-constant limit is 128 bytes");
static_assert(sizeof(ShadowPush)==128, "Shadow push constants must fit Vulkan minimum limit");
struct FrustumPlane { Vec3 normal; float distance; };
std::array<FrustumPlane,6> extract_frustum(const Mat4& m) {
 const float r[4][4]={{m.v[0],m.v[4],m.v[8],m.v[12]},{m.v[1],m.v[5],m.v[9],m.v[13]},{m.v[2],m.v[6],m.v[10],m.v[14]},{m.v[3],m.v[7],m.v[11],m.v[15]}};
 const float p[6][4]={{r[3][0]+r[0][0],r[3][1]+r[0][1],r[3][2]+r[0][2],r[3][3]+r[0][3]},{r[3][0]-r[0][0],r[3][1]-r[0][1],r[3][2]-r[0][2],r[3][3]-r[0][3]},{r[3][0]+r[1][0],r[3][1]+r[1][1],r[3][2]+r[1][2],r[3][3]+r[1][3]},{r[3][0]-r[1][0],r[3][1]-r[1][1],r[3][2]-r[1][2],r[3][3]-r[1][3]},{r[2][0],r[2][1],r[2][2],r[2][3]},{r[3][0]-r[2][0],r[3][1]-r[2][1],r[3][2]-r[2][2],r[3][3]-r[2][3]}};
 std::array<FrustumPlane,6> out{}; for(size_t i=0;i<6;i++){float l=std::sqrt(p[i][0]*p[i][0]+p[i][1]*p[i][1]+p[i][2]*p[i][2]);float inv=l>1e-8f?1.0f/l:1.0f;out[i]={{p[i][0]*inv,p[i][1]*inv,p[i][2]*inv},p[i][3]*inv};}return out;
}
bool sphere_visible(const std::array<FrustumPlane,6>& planes,const Mat4& model,Vec3 center,float radius){
 const float x=model.v[0]*center.x+model.v[4]*center.y+model.v[8]*center.z+model.v[12],y=model.v[1]*center.x+model.v[5]*center.y+model.v[9]*center.z+model.v[13],z=model.v[2]*center.x+model.v[6]*center.y+model.v[10]*center.z+model.v[14];
 const float sx=std::sqrt(model.v[0]*model.v[0]+model.v[1]*model.v[1]+model.v[2]*model.v[2]),sy=std::sqrt(model.v[4]*model.v[4]+model.v[5]*model.v[5]+model.v[6]*model.v[6]),sz=std::sqrt(model.v[8]*model.v[8]+model.v[9]*model.v[9]+model.v[10]*model.v[10]);const float r=radius*std::max({sx,sy,sz});
 for(const auto&p:planes)if(dot(p.normal,{x,y,z})+p.distance < -r)return false;return true;
}
